	title 'QD Conics            GS ROM 1.1'*****************************************************************			   **	   Conics		   **			   **********************************************************************************************************************************			   **              Copyright (C) 1985-1987		   **              All Rights Reserved		   **              Apple Computer, Inc.		   **			   *****************************************************************	include 'all.macros'		MACRO&lab	MoveL &Label1,&Label2&lab	lda &Label1	sta &Label2	lda &Label1+2	sta &Label2+2	MEND	MACRO&lab	MoveP &Label1,&Label2&lab	lda &Label1,s	sta &Label2	lda &Label1+2,s	sta &Label2+2	MEND	MACRO&lab	PushNil&lab	lda #0	pha	pha	MEND	MACRO&lab	IncYWd&lab	iny	iny	MEND	MACRO&lab	DecYWd&lab	dey	dey	MEND	MACRO&lab	IncYPtr&lab	iny	iny	iny	iny	MEND	MACRO&lab	DecYPtr&lab	dey	dey	dey	dey	MEND	MACRO&lab	MoveLong &From,&To&lab	lda &From	sta &To	lda &From+2	sta &To+2	MEND	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:rect.equs'	INCLUDE ':QDEquates:slab.equs'	INCLUDE ':QDEquates:conics.equs';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyErr	IMPORT CommonSlabSetup	IMPORT DerefHandle	IMPORT NextPatSlice	IMPORT QDStart	IMPORT ReSizeHandle	IMPORT RgnSave	IMPORT SetFirstDestRef	IMPORT SetNextDestRef	IMPORT TestGPs	IMPORT UnlockHandle;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY CallArc	ENTRY CallOval	ENTRY CallRRect	ENTRY ConicGetRect	ENTRY FrConic	ENTRY GetAngles	ENTRY GetWandH	ENTRY OvalPenSize	ENTRY iStdConic;                copy conics/conics*	   Table of Contents** 1.  Ovals**       FrameOval	   Frames an oval*       PaintOval	   Paints an oval in the current pattern*       EraseOval	   Erases an oval*       InvertOval	   Inverts an oval*       FillOval	   Fills an oval with a pattern*       CallOval	   The oval bottleneck procedure*       iStdConic	   The standard conic routine, passed #?Noun in A** 2.  Round Rects**       FrameRRect	   Frames a round rect*       PaintRRect	   Paints a round rect in the current pattern*       EraseRRect	   Erases a round rect*       InvertRRect	   Inverts a round rect*       FillRRect	   Fills a round rect with a pattern*       CallRRect	   The round rect bottleneck procedure** 3. Arcs**       FrameArc	   Frames an arc*       PaintArc	   Paints an arc in	the current pattern*       EraseArc	   Erases an arc*       InvertArc	   Inverts an arc*       FillArc	   Fills an arc with a pattern*       CallArc	   The arc bottleneck procedure** 4. Environment and utility calls**       ConicGetRect   Pulls rect into Y1... and OuterOval+OvalTop...*       GetWandH	   Pulls OvalWidth and OvalHeight off stack*       GetAngles	   Pulls StartAngle	and ArcAngle off stack*       AngleFromSlope Just like it sounds*       SlopeFromAngle Just like this sounds, too*       InitOval	   Support routine for oval drawing*       BumpOval	   Bumps oval state	record to next scan	line*       SetArcRot	   Sets the grafport parameter for arc/oval rotation*       GetArcRot	   Returns the grafport parameter for oval rotation****************************************************************** FrameOval(r:Rect)*****************************************************************	EXPORT FrameOvalFrameOval	PROC*              using PicInfo	jsr QDStart	jsr ConicGetRect	sec	lda Y2	sbc Y1	sta Rect2+2	sec	lda X2	sbc X1	sta Rect2	ldx #FrameVerb	jsl CallOval	tax	ldy #4	jmp BusyErr	ENDP****************************************************************** PaintOval(r:Rect)*****************************************************************	EXPORT PaintOvalPaintOval	PROC*              using PicInfo	jsr QDStart	jsr ConicGetRect	ldx #PaintVerb	jsl CallOval	tax	ldy #4	jmp BusyErr	ENDP****************************************************************** EraseOval(r:Rect)*****************************************************************	EXPORT EraseOvalEraseOval	PROC*              using PicInfo	jsr QDStart	jsr ConicGetRect	ldx #EraseVerb	jsl CallOval	tax	ldy #4	jmp BusyErr	ENDP****************************************************************** InvertOval(r:Rect)*****************************************************************	EXPORT InvertOvalInvertOval	PROC*              using PicInfo	jsr QDStart	jsr ConicGetRect	ldx #InvertVerb	jsl CallOval	tax	ldy #4	jmp BusyErr	ENDP****************************************************************** FillOval(r:Rect; p:Pattern)*****************************************************************	EXPORT FillOvalFillOval	PROC*              using PicInfo*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PPtr	equ RTL2+3RPtr	equ PPtr+4	jsr QDStart	jsl UserPat2ZP	lda RPtr,s	sta PPtr,s	lda RPtr+2,s	sta PPtr+2,s	jsr ConicGetRect	ldx #FillVerb	jsl CallOval	tax	ldy #8	jmp BusyErr	ENDP****************************************************************** CallOval** This routine is jumped (or branched) to by the entry points* after the graf verb is loaded into the X register.* Zero page is already switched in by the time it gets here.** Change History** 23 Oct 88	Steven Glass** The extra variables were being set after looking at the* bottleneck pointer so that if there were custom bottleneck* procs, these vars would not be setup correctly.*****************************************************************CallOval	PROC	stx DrawVerb	; save the verb	;-----------------------------------------------------------;; Set up the other variables and then get call correct routine.;		lda #360	; a full oval	sta ArcAngle	stz StartAngle	ldx #OuterOval	sec	lda Y2	sbc Y1	sta OvalHeight,x	sec	lda X2	sbc X1	sta OvalWidth,x;-----------------------------------------------------------;; Now, see how do we get there.	jsr TestGPs	; if there is a gp pointer	bcs UseLocal	jml StdOvalUseLocal	phb	; put extra byte on	stack	ldy #o_stdoval	; get adr of new Oval routine	lda [temp],y	; put on stack	pha	iny	; get bytes 2 and 3	lda [temp],y	sta 2,s	; store middle byte	twice	rtl	; call it	ENDP****************************************************************** iStdConic** Common conic routine that is central point for all oval drawing.** When control gets	here, all inputs are on zero page.*       TheRect is kept in Y1 thru X2*       ThePat (if any) is in TheFillPat*       WhatToDo is	in DrawVerb*****************************************************************	EXPORT StdStuffStdStuff	PROC*              using CoreDATA*              using PicInfo*              using QDProcs*              using E0Vectors	EXPORT iStdArciStdArc		;       	lda #ArcNoun	bra iStdConic	EXPORT iStdOvaliStdOval		;       	lda #OvalNoun	bra iStdConic	EXPORT iStdRRectiStdRRect		;       	lda #RRectNoun	EXPORT iStdConiciStdConic		;       	sta DrawNoun	jsl PutPictStuff	; inputs on zp and in a-reg	bcc NoPicErr	rtl	; return the errorNoPicErr		; 	stz HollowFlag	; ToFrConic overrides this below	lda DrawVerb	; put verb in a	bne NotFrame	lda DrawNoun	cmp #ArcNoun	beq ToFrConic	jsr RgnSave	; does this contribute to region def	bcc ToFrConic	; no, so frame it	jsl PutOval	; yes, so call putrect	bcc ToFrConic	; no error so frame	it.	rtl	; return the errorToFrConic	inc HollowFlag	; we want a hollow oval	brl FrConicNotFrame		; 	jmp CommonSlabSetup	ENDP****************************************************************** FrameRRect(r:Rect)*****************************************************************	EXPORT FrameRRectFrameRRect	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3oheight	equ RTL2+3owidth	equ oHeight+2RPtr	equ oWidth+2*              using PicInfo	jsr QDStart	jsr GetWandH	ldx #OuterOval	lda OvalHeight,x	sta Rect2+2	lda OvalWidth,x	sta Rect2	lda RPtr,s	sta oHeight,s	lda RPtr+2,s	sta oHeight+2,s	jsr ConicGetRect	ldx #FrameVerb	jsl CallRRect	tax	ldy #8	jmp BusyErr	ENDP****************************************************************** PaintRRect(r:Rect)*****************************************************************	EXPORT PaintRRectPaintRRect	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3oheight	equ RTL2+3owidth	equ oHeight+2RPtr	equ oWidth+2*              using PicInfo	jsr QDStart	jsr GetWandH	lda RPtr,s	sta oHeight,s	lda RPtr+2,s	sta oHeight+2,s	jsr ConicGetRect	ldx #PaintVerb	jsl CallRRect	tax	ldy #8	jmp BusyErr	ENDP****************************************************************** EraseRRect(r:Rect)*****************************************************************	EXPORT EraseRRectEraseRRect	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3oheight	equ RTL2+3owidth	equ oHeight+2RPtr	equ oWidth+2*              using PicInfo	jsr QDStart	jsr GetWandH	lda RPtr,s	sta oHeight,s	lda RPtr+2,s	sta oHeight+2,s	jsr ConicGetRect	ldx #EraseVerb	jsl CallRRect	tax	ldy #8	jmp BusyErr	ENDP****************************************************************** InvertRRect(r:Rect)*****************************************************************	EXPORT InvertRRectInvertRRect	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3oheight	equ RTL2+3owidth	equ oHeight+2RPtr	equ oWidth+2*              using PicInfo	jsr QDStart	jsr GetWandH	lda RPtr,s	sta oHeight,s	lda RPtr+2,s	sta oHeight+2,s	jsr ConicGetRect	ldx #InvertVerb	jsl CallRRect	tax	ldy #8	jmp BusyErr	ENDP****************************************************************** FillRRect(r:Rect;	p:Pattern)*****************************************************************	EXPORT FillRRectFillRRect	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PPtr	equ RTL2+3oheight	equ PPtr+4owidth	equ oHeight+2RPtr	equ oWidth+2*              using PicInfo*              using E0Vectors	jsr QDStart	jsl UserPat2ZP	ldx #OuterOval	lda Oheight,s	sta OvalHeight,x	lda Owidth,s	sta OvalWidth,x	lda RPtr,s	sta PPtr,s	lda RPtr+2,s	sta PPtr+2,s	jsr ConicGetRect	ldx #FillVerb	jsl CallRRect	tax	ldy #12	jmp BusyErr	ENDP****************************************************************** CallRRect** This routine is jumped (or branched) to by the* entry points after the graf verb is loaded into the* x register.** Zero page is already switched in by the time it gets here.** Change History** 23 Oct 88	Steven Glass** The extra variables were being set after looking at the* bottleneck pointer so that if there were custom bottleneck* procs, these vars would not be setup correctly.*****************************************************************CallRRect	PROC	stx DrawVerb;-----------------------------------------------------------;; Now setup arcangle and start angle;	lda #360	; a full oval	sta ArcAngle	stz StartAngle;-----------------------------------------------------------;; Look at grafProcs ptr.	jsr TestGPs	; if there is a gp pointer	bcs UseLocal	jml StdRRectUseLocal	phb	; put extra byte on	stack	ldy #o_stdRRect	; get adr of new RRect routine	lda [temp],y	; put on stack	pha	iny	; get bytes 2 and 3	lda [temp],y	sta 2,s	; store middle byte	twice	rtl	; call it	ENDP****************************************************************** FrameArc(r:Rect; StartAngle,ArcAngle:integer)*****************************************************************	EXPORT FrameArcFrameArc	PROC*              using PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3AAngle	equ RTL2+3SAngle	equ AAngle+2RPtr	equ SAngle+2	jsr QDStart	jsr GetAngles	lda RPtr,s	sta AAngle,s	lda RPtr+2,s	sta AAngle+2,s	jsr ConicGetRect	ldx #FrameVerb	jsl CallArc	tax	ldy #8	jmp BusyErr	ENDP****************************************************************** PaintArc(r:Rect; StartAngle,ArcAngle:integer)*****************************************************************	EXPORT PaintArcPaintArc	PROC*             using	PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3AAngle	equ RTL2+3SAngle	equ AAngle+2RPtr	equ SAngle+2	jsr QDStart	jsr GetAngles	lda RPtr,s	sta AAngle,s	lda RPtr+2,s	sta AAngle+2,s	jsr ConicGetRect	ldx #PaintVerb	jsl CallArc	tax	ldy #8	jmp BusyErr	ENDP****************************************************************** EraseArc(r:Rect; StartAngle,ArcAngle:integer)*****************************************************************	EXPORT EraseArcEraseArc	PROC*              using PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3AAngle	equ RTL2+3SAngle	equ AAngle+2RPtr	equ SAngle+2	jsr QDStart	jsr GetAngles	lda RPtr,s	sta AAngle,s	lda RPtr+2,s	sta AAngle+2,s	jsr ConicGetRect	ldx #EraseVerb	jsl CallArc	tax	ldy #8	jmp BusyErr	ENDP****************************************************************** InvertArc(r:Rect;	StartAngle,ArcAngle:integer)*****************************************************************	EXPORT InvertArcInvertArc	PROC*              using PicInfoOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3AAngle	equ RTL2+3SAngle	equ AAngle+2RPtr	equ SAngle+2	jsr QDStart	jsr GetAngles	lda RPtr,s	sta AAngle,s	lda RPtr+2,s	sta AAngle+2,s	jsr ConicGetRect	ldx #InvertVerb	jsl CallArc	tax	ldy #8	jmp BusyErr	ENDP****************************************************************** FillArc(r:Rect; StartAngle,ArcAngle:integer; p:PatPtr)*****************************************************************	EXPORT FillArcFillArc	PROC*              using PicInfo*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PPtr	equ RTL2+3AAngle	equ PPtr+4SAngle	equ AAngle+2RPtr	equ SAngle+2	jsr QDStart	jsl UserPat2ZP	lda SAngle,s	sta StartAngle	lda AAngle,s	sta ArcAngle	lda RPtr,s	sta PPtr,s	lda RPtr+2,s	sta PPtr+2,s	jsr ConicGetRect	ldx #FillVerb	jsl CallArc	tax	ldy #12	jmp BusyErr	ENDP****************************************************************** CallArc** This routine is jumped (or branched) to by the* entry points after the graf verb is loaded into the* x register.** Zero page is already switched in by the time it gets here.** Change History** 23 Oct 88	Steven Glass** The extra variables were being set after looking at the* bottleneck pointer so that if there were custom bottleneck* procs, these vars would not be setup correctly.*****************************************************************CallArc	PROC	stx DrawVerb;-----------------------------------------------------------;; Setup these other parameters before checking the grafprocs;	ldx #OuterOval	sec	lda Y2	sbc Y1	sta OvalHeight,x	sec	lda X2	sbc X1	sta OvalWidth,x;-----------------------------------------------------------;; Check the grafprocs.;	jsr TestGPs	; if there is a gp pointer	bcs UseLocal	jml StdArcUseLocal	phb	; put extra byte on	stack	ldy #o_stdArc	; get adr of new Arc routine	lda [temp],y	; put on stack	pha	iny	; get bytes 2 and 3	lda [temp],y	sta 2,s	; store middle byte	twice	rtl	; call it	ENDP****************************************************************** ConicGetRect** Gets the rectangle pointer off the stack, and copies the rect* to Y1..X2 and to OuterOval+OvalTop..OvalRight*****************************************************************	EXPORT ConicGetRectConicGetRect	PROCRTSAdr	equ 1OrigDirect	equ RTSAdr+2RTL1	equ OrigDirect+2RTL2	equ RTL1+3RPtr	equ RTL2+3	lda RPtr,s	sta Temp	lda RPtr+2,s	sta Temp+2	ldx #OuterOval+6	ldy #6PLoop	phx	tyx	lda [Temp],y	sta Y1,x	plx	sta OvalTop,x	dex	dex	dey	dey	bpl PLoop	rts	ENDP****************************************************************** GetWandH** Gets the width and height off the stack and puts them on* zero page.*****************************************************************	EXPORT GetWandHGetWandH	PROCRtsAdr	equ 1OrigDirect	equ RtsAdr+2RTL1	equ OrigDirect+2RTL2	equ RTL1+3Oheight	equ RTL2+3Owidth	equ oHeight+2	ldx #OuterOval	lda Oheight,s	sta OvalHeight,x	lda Owidth,s	sta OvalWidth,x	rts	ENDP****************************************************************** GetAngles** Gets the StartAngle and ArcAngle off the stack and puts them on* zero page.*****************************************************************	EXPORT GetAnglesGetAngles	PROCRtsAdr	equ 1OrigDirect	equ RtsAdr+2RTL1	equ OrigDirect+2RTL2	equ RTL1+3AAngle	equ RTL2+3SAngle	equ AAngle+2	lda SAngle,s	sta StartAngle	lda AAngle,s	sta ArcAngle	rts	ENDP****************************************************************** Function iAngleFromSlope:integer*****************************************************************	EXPORT iAngleFromSlopeiAngleFromSlope	PROC* Parameter is passed in Slope, which is equated with Temp2.  This* routine destroys Temp as well (Angle and SlopeSign).  When it* calls SlopeFromAngle it also destroys	Slope2.  To begin* make the slope positive, but remember	the sign.	stz SlopeSign	; zero slope sign boolean	asl Slope+2	; move sign into carry	rol SlopeSign	; and into SlopeSign	beq PositiveSlope* Negate slope to make it positive	lda Slope	eor #$FFFF	ina	sta Slope	beq NoDockHigh	dec Slope+2	; becomes a carry after eor #$FFFFNoDockHigh	lda Slope+2	eor #$FFFF	sta Slope+2PositiveSlope	sec	; bias the compare by 500	lda Slope	sbc #500	bcs NoDock1	dec Slope+2NoDock1	stz Angle	bra ScanInsideScan	inc Angle	; A2Slope won't change itScanInside	jsr A2Slope	; returns the slope	for Angle	lda Slope2+2	cmp Slope+2	bmi Scan	bne FoundIt	lda Slope2	cmp Slope	bmi Scan* We equal or exceed Slope, so we've found itFoundIt	lda SlopeSign	beq DontInvertIt	sec	lda #180	sbc Angle	sta AngleDontInvertIt	rtl* SlopeFromAngle uses the zero page value Angle (which falls on top of* Temp) and returns	its result in Slope2 (which makes life convenient* for DrawArc, actually).  SlopeSign overlaps Temp+2.	EXPORT iSlopeFromAngleiSlopeFromAngle		;       	lda Angle	bra AngleCmpTruncAngle	sec	sbc #180AngleCmp	cmp #180	bpl TruncAngle	tax	; to set flags on A	bpl AngleOkayPushAngle	clc	adc #180	bmi PushAngleAngleOkay	sta Angle	; angle is in the range 0..179	stz SlopeSign	cmp #91	bmi NotOverNinety	inc SlopeSign	sec	sbc #180	eor #$FFFF	ina	sta AngleNotOverNinety	jsr A2Slope	lda SlopeSign	bne Done	lda Slope2	eor #$FFFF	ina	sta Slope2	bne NoDockSlope	dec Slope2+2NoDockSlope	lda Slope2+2	eor #$FFFF	sta Slope2+2Done	rtl* A2Slope is the local routine that does all the work.A2Slope	lda #90	cmp Angle	bne NonNinety	lda #MaxInt	; this may be wrong	sta Slope2+2	lda #$FFFF	sta Slope2	rtsNonNinety	stz Slope2+2	lda Angle	; if Angle < 45, Slope+2 = 0	cmp #45	bmi Share	inc Slope2+2	; if Angle < 64, Slope+2 = 1	cmp #64	bmi Share	tax	; use it as an index	lda >HiSlopeTab-60,x ; pick up the high	word, low byte	and #$00FF	; only 90 deg has anything in high byte	sta Slope2+2	; save the high word	lda Angle	; get the low wordShare	asl A	tax	lda >SlopeTable,x	sta Slope2	rts*              dc i1'$01,$01,$01,$01,$01'       ; 45-49*              dc i1'$01,$01,$01,$01,$01'       ; 50-54*              dc i1'$01,$01,$01,$01,$01'       ; 55-59HiSlopeTab	DC.B $01,$01,$01,$01,$02 ; 60-64	DC.B $02,$02,$02,$02,$02 ; 65-69	DC.B $02,$02,$03,$03,$03 ; 70-74	DC.B $03,$04,$04,$04,$05 ; 75-79	DC.B $05,$06,$07,$08,$09 ; 80-84	DC.B $0B,$0E,$13,$1C,$39 ; 85-89SlopeTable	DC.W $0000	; 0	DC.W $0478	DC.W $08F1	DC.W $0D6B	DC.W $11E7	DC.W $1666	; 5	DC.W $1AE8	DC.W $1F6F	DC.W $23FA	DC.W $288C	DC.W $2D24	; 10	DC.W $31C3	DC.W $366A	DC.W $3B1A	DC.W $3FD4	DC.W $4498	; 15	DC.W $4968	DC.W $4E44	DC.W $532E	DC.W $5826	DC.W $5D2D	; 20	DC.W $6245	DC.W $676E	DC.W $6CAA	DC.W $71FB	DC.W $7760	; 25	DC.W $7CDC	DC.W $8270	DC.W $881E	DC.W $8DE7	DC.W $93CD	; 30	DC.W $99D2	DC.W $9FF7	DC.W $A640	DC.W $ACAD	DC.W $B341	; 35	DC.W $B9FF	DC.W $C0E9	DC.W $C802	DC.W $CF4E	DC.W $D6CF	; 40	DC.W $DE8A	DC.W $E681	DC.W $EEB9	DC.W $F737	DC.W $0000	; 45	DC.W $0919	DC.W $1287	DC.W $1C51	DC.W $267F	DC.W $3117	; 50	DC.W $3C22	DC.W $47AA	DC.W $53B9	DC.W $605B	DC.W $6D98	; 55	DC.W $7B89	DC.W $8A35	DC.W $99AF	DC.W $AA0E	DC.W $BB68	; 60	DC.W $CDD6	DC.W $E177	DC.W $F66E	DC.W $0CE1	DC.W $24FE	; 65	DC.W $3EFC	DC.W $5B19	DC.W $799F	DC.W $9AE7	DC.W $BF5B	; 70	DC.W $E77A	DC.W $13E3	DC.W $4556	DC.W $7CC7	DC.W $BB68	; 75	DC.W $02C2	DC.W $54DB	DC.W $B462	DC.W $2501	DC.W $ABD9	; 80	DC.W $5051	DC.W $1D88	DC.W $24F3	DC.W $83AD	DC.W $6E17	; 85	DC.W $4CF5	DC.W $14BD	DC.W $A2D7	DC.W $4A30	DC.W $FFFF	; 90	ENDP******************************************************************              iInitOval*****************************************************************	EXPORT iInitOvaliInitOval	PROC* When we enter, x points at the proper	oval record, which may not* be in the first zero page (it's probably in the 3rd zero page, actually).* Note that the stz	instruction can't be used.* The oval rectangle is set up by the caller, so we'll just leave it where* it already is.  That's just dandy by us.  Pin OvalHeight and OvalWidth* to a minimum of 0.	lda OvalHeight,x	bpl HeightOkay	lda #0	sta OvalHeight,xHeightOkay	lda OvalWidth,x	bpl WidthOkay	lda #0	sta OvalWidth,x* Pin OvalHeight (OvalWidth) to a maximum of DestHeight (DestWidth)WidthOkay	sec	lda OvalRight,x	sbc OvalLeft,x	cmp OvalWidth,x	bpl OWidthOkay	sta OvalWidth,xOWidthOkay	sec	lda OvalBottom,x	sbc OvalTop,x	cmp OvalHeight,x	bpl OHeightOkay	sta OvalHeight,x* Set up oval left edge and oval right edge, fixed point numbers.  To* begin with, set things to be zeroed to zero while we have	#0 in AOHeightOkay	lda #0	sta ORightEdge,x	sta OLeftEdge,x	sta Square,x	sta Square+2,x	sta Square+4,x	sta Square+6,x	sta Rsqysq+2,x	lda OvalRight,x	sta ORightEdge+2,x	lda OvalLeft,x	sta OLeftEdge+2,x	stz Temp	lda OvalWidth,x	sta Temp+2	lsr Temp+2	ror Temp	clc	lda OLeftEdge,x	adc Temp	sta OLeftEdge,x	lda OLeftEdge+2,x	adc Temp+2	sta OLeftEdge+2,x	sec	lda ORightEdge,x	sbc Temp	sta ORightEdge,x	lda ORightEdge+2,x	sbc Temp+2	sta ORightEdge+2,x	clc	lda #$8000	adc ORightEdge,x	sta ORightEdge,x	bcc T1	inc ORightEdge+2,xT1	lda OvalHeight,x	; calc 1-OvalHeight	eor #$FFFF	; negate it	ina	ina	sta OvalY,x	lda OvalHeight,x	asl A	; double it	dea	; -1	sta Rsqysq,x* OddNum := (AspectRatio ^2), and while	we're at it we can set* OddBump := 2 * (AspectRatio ^2) by just storing it and rotating* it at the same time.	phx	; save x	pea 0	; push 64 bit result	pea 0	pea 0	pea 0	pea 0	; push 32 bit result	pea 0	lda OvalHeight,x	pha	lda OvalWidth,x	pha	_FixRatio	lda 3,s	; duplicate high word	pha	lda 3,s	; duplicate low word	pha	_LongMul	; calc 64 bit (Height/Width) squared	lda 9,s	; get x back	tax	pla	sta OddNum,x	asl A	sta OddBump,x	pla	sta OddNum+2,x	rol A	sta OddBump+2,x	pla	sta OddNum+4,x	rol A	sta OddBump+4,x	pla	sta OddNum+6,x	rol A	sta OddBump+6,x	plx	; clean the stack	rtl	ENDP******************************************************************              iBumpOval*****************************************************************	EXPORT iBumpOvaliBumpOval	PROC	lda CurrentY	cmp OvalTop,x	bmi GoHome	cmp OvalBottom,x	bmi While1GoHome	rtl* While square < Rsqysq do make oval biggerMore1		; * ORightedge := ORightedge + 1/2	lda ORightEdge,x	clc	adc #$8000	; one half	sta ORightEdge,x	bcc NoBump1	inc ORightEdge+2,x* OLeftEdge := OLeftEdge - 1/2NoBump1	lda OLeftEdge,x	sec	sbc #$8000	; one half	sta OLeftEdge,x	bcs NoDock1	dec OLeftEdge+2,x* Square := Square + OddNumNoDock1	clc	lda Square,x	adc OddNum,x	sta Square,x	lda Square+2,x	adc OddNum+2,x	sta Square+2,x	lda Square+4,x	adc OddNum+4,x	sta Square+4,x	lda Square+6,x	adc OddNum+6,x	sta Square+6,x* OddNum := OddNum + OddBump	clc	lda OddNum,x	adc OddBump,x	sta OddNum,x	lda OddNum+2,x	adc OddBump+2,x	sta OddNum+2,x	lda OddNum+4,x	adc OddBump+4,x	sta OddNum+4,x	lda OddNum+6,x	adc OddBump+6,x	sta OddNum+6,xWhile1	lda Square+6,x	cmp Rsqysq+2,x	; is Square < Rsqysq ?* Note: the 65816 cmp instruction doesn't work right.  Since square and* Rsqysq should always be positive, use	an unsigned branch instruction.	bcc More1	; yes, loop	bne NotLess	; no, continue* The high words were equal.  Check the	low words.	lda Square+4,x	cmp Rsqysq,x	; is Square < Rsqysq ?	bcc More1NotLess	bra While2	; now backtrack* While Square > Rsqysq do make oval smaller* ORightedge := ORightedge - 1/2More2	sec	lda ORightEdge,x	; get ORightEdge	sbc #$8000	; one half	sta ORightEdge,x	; save it	bcs NoDock2	dec ORightEdge+2,x* OLeftEdge := OLeftEdge + 1/2NoDock2	clc	lda OLeftEdge,x	; get OLeftEdge	adc #$8000	; one half	sta OLeftEdge,x	; save it	bcc NoBump2	inc OLeftEdge+2,x* OddNum := OddNum - OddBumpNoBump2	sec	lda OddNum,x	sbc OddBump,x	sta OddNum,x	lda OddNum+2,x	sbc OddBump+2,x	sta OddNum+2,x	lda OddNum+4,x	sbc OddBump+4,x	sta OddNum+4,x	lda OddNum+6,x	sbc OddBump+6,x	sta OddNum+6,x* Square := Square - OddNum	sec	lda Square,x	sbc OddNum,x	sta Square,x	lda Square+2,x	sbc OddNum+2,x	sta Square+2,x	lda Square+4,x	sbc OddNum+4,x	sta Square+4,x	lda Square+6,x	sbc OddNum+6,x	sta Square+6,xWhile2	lda Rsqysq+2,x	cmp Square+6,x	; is Square > Rsqysq ?* Note: the 65816 cmp instruction doesn't work right.  Since square and* Rsqysq should always be positive, use	an unsigned branch instruction.	bcc More2	; yes, make oval smaller	bne NotMore	; no, continue* The high words were equal.  Check the	low words	lda Rsqysq,x	cmp Square+4,x	; is Square > Rsqysq ?	bcc More2NotMore	lda OvalY,x	ina	; bump by 2	sta Temp	; capture this value	ina	sta OvalY,x	; save it like we promised we would	stz Temp+2	lda Temp	bpl NotNegative	lda #$FFFF	sta Temp+2NotNegative	asl Temp	rol Temp+2	asl Temp	rol Temp+2	sec	lda Rsqysq,x	sbc Temp	sta Rsqysq,x	lda Rsqysq+2,x	sbc Temp+2	sta Rsqysq+2,x	rtl	ENDP;                copy conics/drawconic*	   Table of Contents** 1.  DrawConic**       FrConic	   Frames a conic*       PConic	   Paints a conic in the current pattern*       EConic	   Erases a conic*       IConic	   Inverts a conic*       FConic	   Fills a conic*       OvalPenSize	   Sets up the pen size or exits, as appropriate*       DrawConic	   Draws a conic****************************************************************** PConic, FrConic*****************************************************************	EXPORT FrConicFrConic	PROC*              using E0Vectors	jsr OvalPenSize	; don't come back unless visible	jmp CommonSlabSetup	ENDP****************************************************************** OvalPenSize** Get the PnSize from the port and puts	it in PenWidth and* PenHeight.  It also checks to see if either is 0.  If it is then* we do an rtl for the calling routine.*****************************************************************	EXPORT OvalPenSizeOvalPenSize	PROC* PenWidth and PenHeight overlap Temp2.	 This routine should be called* just before using	them or they'll be wiped away...*              using CoreDATA	ldy #O_PnSize	lda [PortRef],y	beq NowWaitAMin	sta PenHeight	iny	iny	lda [PortRef],y	beq NowWaitAMin	sta PenWidth	rtsNowWaitAMin	pla	; get rts adr off stack	clc	; remember that this terminates call	lda #0	; with no error	rtl	; do rtl for calling routine	ENDP****************************************************************** DrawConic** The common arc, oval, and round rect drawing routine.  Draws* within OvalRect with a curvature specified by OvalWidth* and OvalHeight and an angle from StartAngle to StartAngle+ArcAngle.** By the time control reaches any of the Conic routines, StartAngle,* ArcAngle, HollowFlag, OvalTop..OvalRight, OvalWidth and OvalHeight* have all been set	properly.  When ready to do a slab, we put our* calculated endpoints in X1 and X2 and	call the slab routine.*****************************************************************	EXPORT iDrawConiciDrawConic	PROC*              using E0Vectors* Adjust if ArcAngle negative, quit if Arc = 0	lda ArcAngle	bne NotZeroAngle	rtlNotZeroAngle	phb	; save the bank reg	here* Init2Regions takes RgnA and RgnB and does all the init stuff nec.* for seekrgn.	jsl Init2Regions* SetSlabAdr uses penmode and flag called rgns are rect and	it decides* which is the appropriate slab routine.	jsl SetSlabAdr	; sets up the slab adr on zp	lda ArcAngle	bpl PositiveAngle	clc	adc StartAngle	sta StartAngle	lda ArcAngle	eor #$FFFF	ina	sta ArcAnglePositiveAngle	stz ArcFlag	; initialize	cmp #360	; is arc angle < 360 ?	bmi ItsAnArc	brl NotAnArcItsAnArc	lda StartAngle	; it IS an arc!	jsr CheckAngle	sta StartAngle	; in case it changed	clc	adc ArcAngle	; calc StopAngle	jsr CheckAngle	sta StopAngle	ldx #OuterOval	clc	lda OvalTop,x	adc OvalBottom,x	clc	bpl ItsPlus1	secItsPlus1	ror a	sta MidVert	; MidVert := (top+bottom)/2	clc	lda OvalLeft,x	adc OvalRight,x	clc	bpl ItsPlus2	secItsPlus2	ror a* MidHoriz overlaps	OldRight, considered a temp for this	sta MidHoriz	; MidHoriz := (left+right)/2	pea 0	; space for result	pea 0	sec	lda OvalRight,x	sbc OvalLeft,x	pha	sec	lda OvalBottom,x	sbc OvalTop,x	sta ArcFlag	; a temp, save for later	pha	_FixRatio	pla	sta Line1	; another temp, for	the aspect ratio	pla	sta Line1+2* Calculate Slope1 from StartAngle	lda StartAngle	sta Angle	; SlopeFromAngle's input	jsl vSlopeFromAngle	pea 0	; _FixMul functon result	pea 0	pei Slope2+2	; push SlopeFromAngle's result	pei Slope2	pei Line1+2	; push the aspect ratio temp	pei Line1	_FixMul	pla	sta Slope1	pla	sta Slope1+2* Calculate Slope2 from StopAngle	lda StopAngle	sta Angle	; SlopeFromAngle's input	jsl vSlopeFromAngle	pea 0	; _FixMul function result	pea 0	pei Slope2+2	; push SlopeFromAngle's result	pei Slope2	pei Line1+2	; push the aspect ratio temp	pei Line1	_FixMul	pla	sta Slope2	pla	sta Slope2+2* Initialize Line1 := Fixed(MidHoriz) -	Slope1 * Fixed(Height div 2).  Height* was saved in ArcFlag, above.	pea 0	; result of FixMul	pea 0	lda ArcFlag	; calc Height div 2	lsr A	eor #$FFFF	; negate it	ina	sta ArcFlag	; save it, modified, for later	pha	pea 0	; a low word of 0	pei Slope1+2	pei Slope1	_FixMul	pla	sta Line1	; low word not affected by MidHoriz	pla	clc	adc MidHoriz	; add in MidHoriz	sta Line1+2	; ta dah!* Initialize Line2 := Fixed(MidHoriz) -	Slope2 * Fixed(Height div 2).* -(Height div 2) was saved in ArcFlag,	above.	pea 0	; result of FixMul	pea 0	pei ArcFlag	; from our friend, above	pea 0	; a low word of 0	pei Slope2+2	pei Slope2	_FixMul	pla	sta Line2	; low word not affected by MidHoriz	pla	clc	adc MidHoriz	; add in MidHoriz	sta Line2+2	; ta dah!* Set up Flag1 and Flag2 to tell which half each line is active in.* The code is, negative = active in top, positive = active in bottom, and* 0 = horizontal.	lda StartAngle	; is StartAngle < 180 ?	cmp #180	bpl T1	; no, continue	sec	sbc #90	; yes, Flag1 := StartAngle-90	bra T2T1	sec	lda #270	sbc StartAngle	; Flag1 := 270-StartAngleT2	sta Flag1	lda StopAngle	; is StopAngle < 180 ?	cmp #180	bpl T3	; no, continue	sec	sbc #90	; yes, Flag2 := StopAngle-90	bra T4T3	sec	lda #270	sbc StopAngle	; Flag2 := 270-StopAngleT4	sta Flag2* Set up SkipFlag to skip over unused arc portions	stz SkipFlag	; initialize to zero	lda #180	; is ArcAngle > 180	?	cmp ArcAngle	bmi Obtuse	; skip if angle > 180	bne Acute	; deal with acute angle	lda StartAngle	; so, ArcAngle is 180	cmp #90	; skip if StartAngle=90	bne Obtuse	inc SkipFlag	bra ObtuseAcute	lda Flag1	; SkipFlag := (Flag1 | Flag2) > 0	ora Flag2	bmi Obtuse	inc SkipFlagObtuse	lda #1	; restore our temp to True	sta ArcFlagNotAnArc		; * Init outer oval state record	ldx #OuterOval	jsl InitOval* Calculate SkipTop	and SkipBot	lda OvalHeight,x	; get oval height	lsr A	; calc oval height div 2	sta Temp	adc OvalTop,x	; add oval top	sta SkipTop	; save it	sec	lda OvalBottom,x	sbc Temp	sta SkipBot* If this is a hollow oval, then calculate DstRect inset by* pensize and iInitOval.  If inneroval is empty, switch to a solid oval.	stz InnerFlag	ldx #512	lda HollowFlag	beq Solid	ldx #OuterOval	jsr OvalPenSize	; this will return - it did once	sec	lda OvalRight,x	sbc PenWidth	sta InnerRight	clc	lda OvalLeft,x	adc PenWidth	sta InnerLeft	cmp InnerRight	bpl Solid	sec	lda OvalBottom,x	sbc PenHeight	sta OuterRight	clc	lda OvalTop,x	adc PenHeight	sta OuterLeft	cmp OuterRight	bpl Solid* Initialize the inner oval	inc InnerFlag	; we mean business	ldx #InnerOval	lda InnerRight	; inner right	sta OvalRight,x	lda InnerLeft	; inner left	sta OvalLeft,x	lda OuterRight	; inner bottom	sta OvalBottom,x	lda OuterLeft	; inner top	sta OvalTop,x	ldx #OuterOval	lda PenWidth	; InnerWidth := OvalWidth-2*PenWidth	asl A	eor #$FFFF	ina	clc	adc OvalWidth,x	sta InnerRight	; temp	lda PenHeight	; InnerHeight := OvalHeight-2*PenHeight	asl A	eor #$FFFF	ina	clc	adc OvalHeight,x	ldx #InnerOval	sta OvalHeight,x	lda InnerRight	sta OvalWidth,x	jsl InitOval	; with x set to InnerOval offset* Grab OuterOval.OvalTop and figure out	where in the pixel map its* scan line is.Solid	ldx #OuterOval	lda OvalTop,x	sta CurrentY	sec	sbc BoundsRect	jsr SetFirstDestRefOvalLoop		; ; Now pull out right slice for current y	jsr NextPatSlice; takes as input currentY (global), seek of RgnA and RgnB (clip and vis)	jsl Seek2Regions	ldx #OuterOval	lda OLeftEdge,x	; save away old values for inner	sta OldOuterLeft	lda ORightEdge+2,x	sta OldOuterRight	lda CurrentY	; get current V	cmp SkipTop	; is vert < SkipTop	bmi YesBump	; yes, bump oval record	cmp SkipBot	; is vert >= SkipBot	bmi NoBump	; no, skip bumpingYesBump	ldx #OuterOval	jsl BumpOval	; advance edges	lda InnerFlag	; are we hollow?	beq NoBump	ldx #InnerOval	jsl BumpOval	; advance inner edgesNoBump		; 	lda ArcFlag	bne CheckFlags	brl DoOvalsCheckFlags	lda CurrentY	cmp MidVert	; is CurrentY = MidVert ?	bne NotMid* Adjust arc stuff as we cross the middle vertically	lda Flag1	; invert flags as we cross midpoint	eor #$FFFF	ina	sta Flag1	lda Flag2	eor #$FFFF	ina	sta Flag2* Recalculate SkipFlag and quit if it becomes true - add stuff in here	stz SkipFlag	lda #180	; is ArcAngle > 180	?	cmp ArcAngle	bmi Obtuse1	; skip if angle > 180	bne Acute1	; deal with acute angle	lda StartAngle	; so, ArcAngle is 180	cmp #270	; done if StartAngle=270	bne Obtuse1	brl EurekaAcute1	lda Flag1	; done if (Flag1 | Flag2) > 0	ora Flag2	bmi Obtuse1	brl Eureka* Now swap the roles of Line1 and Line2	as they cross the middleObtuse1	jsr SwapLinesNotMid	lda SkipFlag	beq DoArc	brl NextPat* Solid or hollow arc.  Calculate OuterLeft and OuterRightDoArc		; 	lda CurrentY	cmp MinRect	bpl TopOK1	brl NextPatTopOK1		; 	ldx #OuterOval	lda OLeftEdge+2,x	; get hi word of OuterOval.LeftEdge	ldy Flag1	; is Line1 active?	bpl DA1	cmp Line1+2	; yes, check Line1 horiz coord	bpl DA1	lda Line1+2DA1	sta OuterLeft	lda ORightEdge+2,x	; get hi word of OuterOval.RightEdge	ldy Flag2	; is Line2 active?	bpl DA2	cmp Line2+2	bmi DA2	beq DA2	lda Line2+2DA2	sta OuterRight	lda InnerFlag	beq SArc* may want to double check how currenty	is being used - probably bump* it down near NextPat, not way up here.	ldx #InnerOval	lda CurrentY	cmp OvalTop,x	bmi SArc	cmp OvalBottom,x	bmi HarcSArc	ldx #OuterOval	lda OuterLeft	cmp OuterRight	bpl DividedWedge	sta X1	lda OuterRight	sta X2	jsr DoSlab	brl NextPatDividedWedge	lda Flag1	and Flag2	; are both lines active?	bpl ToNextPat	lda #180	cmp ArcAngle	; is the angle > 180 ?	bpl ToNextPat	lda OLeftEdge+2,x	sta X1	lda OuterRight	sta X2	jsr DoSlab	ldx #OuterOval	lda OuterLeft	sta X1	lda ORightEdge+2,x	sta X2DoASlab	jsr DoSlabToNextPat	brl NextPatHArc		; 	ldx #InnerOval	lda OLeftEdge+2,x	ldy Flag2	bpl HA1	cmp Line2+2	bmi HA1	beq HA1	lda Line2+2HA1	sta InnerLeft	lda ORightEdge+2,x	ldy Flag1	bpl HA2	cmp Line1+2	bpl HA2	lda Line1+2HA2	sta InnerRight* If OuterLeft < OuterRight then paint two slabs	lda OuterLeft	cmp OuterRight	; is OuterLeft < OuterRight ?	bpl HA3	; no, continue	sta X1	lda InnerLeft	sta X2	jsr DoSlab	lda InnerRight	sta X1	lda OuterRight	sta X2	jsr DoSlab	brl NextPat* else if both lines active and angle >	180 then paint two or three slabsHA3	lda Flag1	and Flag2	bmi HABothActive	brl NextPatHABothActive	lda #180	cmp ArcAngle	; is ArcAngle > 180	?	bmi HAAngleOkay	; yes	brl NextPatHAAngleOkay	lda InnerLeft	cmp OuterRight	; is InnerLeft = OuterRight?	bne HA4	; no, continue	lda OuterLeft	sta X1	ldx #InnerOval	; redundant	lda OLeftEdge+2,x	; yes, draw a third	slab	sta X2	bra HA5HA4	lda OuterLeft	cmp InnerRight	bne Not3	lda ORightEdge+2,x	; yes, draw a third	slab	sta X1	lda OuterRight	sta X2HA5	jsr DoSlabNot3		; 	ldx #OuterOval	lda OLeftEdge+2,x	sta X1	lda InnerLeft	sta X2	jsr DoSlab	ldx #OuterOval	lda InnerRight	sta X1	lda ORightEdge+2,x	sta X2	jsr DoSlab	brl NextPat* Branch based on solid or hollow ovalDoOvals		; 	lda CurrentY	cmp MinRect	bpl TopOK2	brl NextPatTopOK2		; 	lda InnerFlag	beq SOval	ldx #InnerOval	lda CurrentY	cmp OvalTop,x	bmi SOval	cmp OvalBottom,x	bpl SOvalHOval	ldx #OuterOval	lda ORightEdge+2,x	pha	lda OLeftEdge+2,x	sta X1	ldx #InnerOval	lda ORightEdge+2,x	pha	lda OLeftEdge+2,x	sta X2	jsr DoSlab	pla	sta X1	pla	sta X2	jsr DoSlab	bra NextPat* Solid oval - draw	one slab between left and right edges of outer ovalSOval	ldx #OuterOval	lda OLeftEdge+2,x	sta X1	lda ORightEdge+2,x	sta X2	jsr DoSlabNextPat	lda CurrentY	ina	cmp MinRect+4	bmi NotYetDoneEureka	plb	; restore bank	rtlNotYetDone	sta CurrentY	lda ArcFlag	; do we need to bump lines?	beq NotLining	clc	lda Slope1	adc Line1	sta Line1	lda Slope1+2	adc Line1+2	sta Line1+2	clc	lda Slope2	adc Line2	sta Line2	lda Slope2+2	adc Line2+2	sta Line2+2NotLining		; 	jsr SetNextDestRef	brl OvalLoop	; loop for all verticals* In this little procedure we do a crude modulo 360 - this will usually* win big because the parameter passed will generally be in	range, but* even if it isn't, this method should still win over the tool call.* Note the status flags coming in must be set on A.CheckAngle	bpl CheckTooHighBumpAngle	clc	adc #360	bmi BumpAngle	rtsDockAngle	sec	sbc #360CheckTooHigh	cmp #360	bpl DockAngle	rts* SwapLines exchanges the meaning of Line1 and Line2 as we cross the middle.* It's put down here to keep the branches in range up above, since all it is* is busy work.SwapLines	lda Flag1	ldx Flag2	stx Flag1	sta Flag2	lda Line1	ldx Line2	stx Line1	sta Line2	lda Line1+2	ldx Line2+2	stx Line1+2	sta Line2+2	lda Slope1	ldx Slope2	stx Slope1	sta Slope2	lda Slope1+2	ldx Slope2+2	stx Slope1+2	sta Slope2+2	rts* XSetup sets left edge and right edge (and maybe a few masks).* Set based upon X1	and X2.DoSlab	lda x2	cmp MinRect+2	bmi DoneSlab	cmp MinRect+6	bmi X2okay	lda MinRect+6	sta X2X2okay	lda x1	cmp MinRect+6	bpl DoneSlab	cmp MinRect+2	bpl X1okay	lda MinRect+2	sta X1X1okay	lda X1	cmp X2	bpl DoneSlab	jsl XSetup	; call in slab routine	jsl ToSlab	; draw slabDoneSlab	rts	ENDP;                copy conics/putoval*	   Table of Contents** PutOval**       iPutOval	   Add oval or round rect points to an open region******************************************************************              iPutOval*****************************************************************	EXPORT iPutOvaliPutOval	PROC*              using E0Vectors*              using ErrorDATA* Init an oval record* Parameters are passed on zero page.  OvalWidth and OvalHeight determine* the shape of the oval.  They are trimmed to DstRect if they are bigger than* it is.  If DstRect is bigger (in either dimension) the extra space is* automatically added along the appropriate axis, generating a round rect.	ldx #OuterOval	jsl InitOval	; go to the vector location	lda OLeftEdge+2,x	sta OldOuterLeft	lda ORightEdge+2,x	sta OldOuterRight	lda OvalHeight,x	; get oval height	lsr A	; calc oval height div 2	clc	adc OvalTop,x	; add oval top	sta SkipTop	; save it	clc	adc OvalBottom,x	; add bottom	sec	sbc OvalTop,x	; subtract top	sec	sbc OvalHeight,x	; subtract OvalHeight	sta SkipBot	; save it* Dereference handle	ldx #BufHandle	jsr DerefHandle	; dereference the current handle	sta BufPtr	; save pointer returned in A & X	stx BufPtr+2	ldy #2	; current index offset	lda [BufPtr],y	; get index	sta Index	; save the pointer to the next point* More initialization	ldx #OuterOval	lda OvalTop,x	sta CurrentY* Put the top edge	lda OldOuterLeft	jsr PutPt	; add it to the buffer	lda OldOuterRight	jsr PutPt	; add this, too* For each vertical, bump OLeftEdge and	ORightEdge.  If they differ from* OOldLeft and OOldRight, put inversion	points for the differences.NxtVert	lda CurrentY	; get current V	cmp SkipTop	; is vert < SkipTop	bmi YesBump	; yes, bump oval record	cmp SkipBot	; is vert >= SkipBot	bmi RightOK	; no, skip bumpingYesBump	ldx #OuterOval	jsl BumpOval	; advance edges, using vector	lda OLeftEdge+2,x	; get OLeftEdge	cmp OldOuterLeft	; same as OOldLeft?	beq LeftOk	; yes, continue	jsr PutPt	; add it to the buffer	lda OldOuterLeft	; get old H	jsr PutPt	; add it to the buffer	lda OLeftEdge+2,x	; get new left	sta OldOuterLeft	; update old left* Check right edge and put two inversion points if it has changed.LeftOk	lda ORightEdge+2,x	; get right edge	cmp OldOuterRight	; same as OOldRight?	beq RightOk	; yes, continue	jsr PutPt	; add it to the buffer	lda OldOuterRight	; get old H	jsr PutPt	; put old right edge	lda ORightEdge+2,x	; get new value	sta OldOuterRight	; update old rightRightOk	lda CurrentY	; bump scan line	ina	sta CurrentY	cmp OvalBottom,x	; are we done yet?	bmi NxtVert	; loop for all verticals* Put the bottom edge	lda OldOuterLeft	jsr PutPt	lda OldOuterRight	jsr PutPt	ldy #2	lda Index	sta [BufPtr],y	; update count	ldx #BufHandle	; unlock the buffer	handle	jsr UnlockHandle	clc	rtl	; go home* Local routine which adds points to the buffer.  The y value is in CurrentY* and the x value is in x.  A handle error from here will go back to the main* caller.PutPt	tax	; save a in x	clc	lda Index	; get current index	tay	; save it just in case	adc #4	; enough room?	sta Index	; the next value	cmp [BufPtr]	; do we have enough	room?	bcc SizeOk	; if we borrowed, that's good	beq SizeOk	; if they're equal, that's good, too	phx	; save the value to	store	phy	; save the index we	need	clc	; prepare for add	adc #1024	; room for 256 more	points	bcs BufferOverflow	; if we wrapped, we're done	ldx #BufHandle	; point X at BufHandle	jsr ReSizeHandle	; resize, relock, rederef	bcs ErrorOut	; if we failed, propogate the error	sta BufPtr	; save pointer	stx BufPtr+2	ply	; restore index	plx	; get the value to store backSizeOk	lda CurrentY	; get the Y value	sta [BufPtr],y	; save the y value	IncYWd	; next integer	txa	; get x value	sta [BufPtr],y	; save the x value	IncYWd	; bump to next point	ldx #OuterOval	rtsBufferOverflow	lda #RgnFull	; error to say we had troublesErrorOut	ply	; we pushed y	plx	; we pushed x	plx	; dump the local return	pha	; push error code	ldx #BufHandle	; unlock the buffer	handle	jsr UnlockHandle	sec	; set the error flag	pla	; pull the error code	rtl	; go home	ENDP	END